"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[945],{1945:(e,a,l)=>{l.d(a,{Ji:()=>s,gL:()=>r,wj:()=>b});let t="https://github.com/Faithlife/SBLGNT/blob/c4d241a9c1c479a55b989ba35a4976c1d0b8052c/data/sblgnt/text/Acts.txt",r="2026-09-30";function s(e){var a,l;let t=Number(null!=(l=null==(a=e.reference.match(/행\s*\d+:(\d+)/))?void 0:a[1])?l:0);return 1e3*e.chapter+t}function n(e,a){return"https://bible.bskorea.or.kr/bible/NKRV/ACT.".concat(e,".").concat(a)}function o(e,a){return"https://bible.bskorea.or.kr/bible/NKT/ACT.".concat(e,".").concat(a)}function i(e,a){return"https://classic.net.bible.org/verse.php?book=Act&chapter=".concat(e,"&verse=").concat(a)}let b=[{id:"acts-1-6-restore-to-israel",chapter:1,reference:"행 1:6",category:"문법\xb7문장",title:"이스라엘에게 나라를 회복시켜 주는 때",revisedPhrase:"“이스라엘 나라를 회복하심이”",newKoreanPhrase:"“이스라엘을 위해 나라를 다시 일으켜 세워 주시려는 것입니까?”",greek:"ἐν τῷ χρόνῳ τούτῳ ἀποκαθιστάνεις τὴν βασιλείαν τῷ Ἰσραήλ",literalReading:"이때에 당신이 이스라엘에게 나라를 회복시키십니까?",possibleReading:"주님, 이스라엘에게 나라를 회복시켜 주실 때가 바로 지금입니까?",explanation:"τὴν βασιλείαν은 회복되는 대상인 ‘나라를’, τῷ Ἰσραήλ은 그 회복의 수혜자인 ‘이스라엘에게’를 나타낸다. 개역개정은 이를 ‘이스라엘 나라’로 묶고, 새한글성경은 ‘이스라엘을 위해’로 구분한다. ἀποκαθιστάνεις는 현재 능동 직설법 2인칭 단수다. 문장 앞의 ‘이때에’가 회복의 시기를 묻는 질문에 초점을 준다. Dunn은 예수님의 대답이 회복의 소망보다 그 시기에 관한 추측을 제한한다고 해석한다.",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 1장 6-8절 주해.",sources:[{label:"개역개정 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKRV/ACT.1.6"},{label:"새한글성경 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKT/ACT.1.6"},{label:"SBLGNT 기준 본문",url:"https://github.com/Faithlife/SBLGNT/blob/c4d241a9c1c479a55b989ba35a4976c1d0b8052c/data/sblgnt/text/Acts.txt"}]},{id:"acts-2-23-handed-over",chapter:2,reference:"행 2:23",category:"문법\xb7문장",title:"넘겨진 예수와 죽인 사람들, 문장의 주어",revisedPhrase:"“그가 … 내준 바 되었거늘” \xb7 “너희가 … 죽였으나”",newKoreanPhrase:"“이분을 하나님이 … 여러분에게 넘겨주셨습니다”",greek:"τοῦτον τῇ ὡρισμένῃ βουλῇ καὶ προγνώσει τοῦ θεοῦ ἔκδοτον … προσπήξαντες ἀνείλατε",literalReading:"하나님의 정해진 뜻과 미리 아심에 따라 넘겨진 이분을 … 여러분이 못 박아 죽였습니다",possibleReading:"예수님은 하나님의 뜻대로 넘겨지셨고, 여러분은 그분을 못 박아 죽였습니다",explanation:"τοῦτον은 ‘이분을’이라는 목적어이며, 문장의 중심 동사 ἀνείλατε는 ‘여러분이 죽였다’라는 2인칭 복수다. ἔκδοτον은 넘겨진 상태를 나타내는 형용사다. 개역개정은 이를 ‘그가 … 내준 바 되었거늘’이라는 절로 풀고, 새한글성경은 하나님의 뜻과의 관계를 ‘하나님이 … 넘겨주셨습니다’라는 별도 문장으로 옮긴다. 두 역본 모두 하나님의 계획과 청중의 행위를 구분하며, 원문은 한 문장 안에서 두 관계를 함께 표현한다.",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 2장 23절 주해.",sources:[{label:"개역개정 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKRV/ACT.2.23"},{label:"새한글성경 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKT/ACT.2.23"},{label:"SBLGNT 기준 본문",url:"https://github.com/Faithlife/SBLGNT/blob/c4d241a9c1c479a55b989ba35a4976c1d0b8052c/data/sblgnt/text/Acts.txt"}]},{id:"acts-3-13-pais",chapter:3,reference:"행 3:13",category:"낱말 의미",title:"하나님의 종 예수, παῖς의 뜻과 배경",revisedPhrase:"“그의 종 예수를 영화롭게 하셨느니라”",newKoreanPhrase:"“자기의 종 예수를 영광스럽게 해 주셨습니다”",greek:"ἐδόξασεν τὸν παῖδα αὐτοῦ Ἰησοῦν",literalReading:"그의 종 예수를 영광스럽게 하셨다",possibleReading:"하나님이 자신의 종 예수님을 영광스럽게 하셨다",explanation:"παῖς는 ‘아이’와 ‘종’을 뜻할 수 있으며, 여기서는 예수를 가리키는 칭호로 쓰인다. αὐτοῦ는 주어인 하나님을 가리키는 ‘그의’다. 두 한국어 역본은 ‘종’을 택했다. Dunn은 종을 영광스럽게 한다는 표현을 LXX 이사야 52장 13절과 연결한다. Jipp은 시편의 다윗 왕을 높이는 약속을 강조하며, 사도행전 4장에서 다윗과 예수에게 같은 παῖς 칭호가 쓰이는 점을 함께 설명한다.",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 3장 13절 주해; Luke Timothy Johnson, The Acts of the Apostles, 67쪽; Joshua W. Jipp, God’s Acts for Israel, Gentiles, and Christians, 63, 99쪽.",sources:[{label:"개역개정 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKRV/ACT.3.13"},{label:"새한글성경 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKT/ACT.3.13"},{label:"SBLGNT 기준 본문",url:"https://github.com/Faithlife/SBLGNT/blob/c4d241a9c1c479a55b989ba35a4976c1d0b8052c/data/sblgnt/text/Acts.txt"}]},{id:"acts-3-16-faith-through-him",chapter:3,reference:"행 3:16",category:"지시 대상",title:"예수를 통한 믿음과 치유받은 사람",revisedPhrase:"“예수로 말미암아 난 믿음이”",newKoreanPhrase:"“그분을 통해 생겨난 믿음이”",greek:"ἡ πίστις ἡ διʼ αὐτοῦ ἔδωκεν αὐτῷ τὴν ὁλοκληρίαν ταύτην",literalReading:"그를 통한 믿음이 그에게 이 온전한 건강을 주었다",possibleReading:"예수님을 통한 믿음이 치유받은 그 사람에게 온전한 건강을 주었다",explanation:"διʼ αὐτοῦ의 αὐτοῦ는 예수님을 가리키고, ἔδωκεν αὐτῷ의 αὐτῷ는 치유받은 사람을 가리킨다. 같은 3인칭 대명사라도 문장에서 맡은 역할과 지시 대상이 다르다. 원문은 ‘그를 통한 믿음’이라고 하며, 두 역본의 ‘난’과 ‘생겨난’은 그 관계를 풀어 쓴 표현이다. 믿음을 가진 사람은 명시되지 않는다. Dunn은 구제를 기대하던 사람보다 예수님의 이름으로 행동한 베드로와 요한의 믿음을 우선하여 읽는다.",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 3장 16절 주해; Luke Timothy Johnson, The Acts of the Apostles, 68쪽.",sources:[{label:"개역개정 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKRV/ACT.3.16"},{label:"새한글성경 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKT/ACT.3.16"},{label:"SBLGNT 기준 본문",url:"https://github.com/Faithlife/SBLGNT/blob/c4d241a9c1c479a55b989ba35a4976c1d0b8052c/data/sblgnt/text/Acts.txt"}]},{id:"acts-4-25-30-your-servant",chapter:4,reference:"행 4:25, 27, 30",category:"지시 대상",title:"당신의 종을 주의 종으로 옮기는 방식",revisedPhrase:"“주의 종 우리 조상 다윗” \xb7 “거룩한 종 예수의 이름으로”",newKoreanPhrase:"“주님이 부리시는 우리 조상 다윗” \xb7 “주님의 거룩한 종 예수님의 이름을 통해서요”",greek:"Δαυὶδ παιδός σου (4:25) \xb7 τὸν ἅγιον παῖδά σου Ἰησοῦν (4:27) \xb7 τοῦ ἁγίου παιδός σου Ἰησοῦ (4:30)",literalReading:"당신의 종 다윗 \xb7 당신의 거룩한 종 예수",possibleReading:"기도를 받으시는 하나님의 종 다윗과 하나님의 거룩한 종 예수",explanation:"σου는 하나님께 직접 말하는 2인칭 단수 ‘당신의’다. 개역개정의 ‘주의 종’은 이 소유 표현을 호칭으로 풀어 쓴 것이다. 사도행전 4장 30절에서 개역개정은 ‘손’과 ‘종’에 붙은 σου를 따로 옮기지 않고, 새한글성경은 두 곳 모두 ‘주님의’를 표시한다. 이 기도는 다윗과 예수를 παῖς로 부르고 공동체는 4장 29절에서 δοῦλοι로 부른다. Jipp은 LXX 시편 2편 인용과 예수님의 기름부음을 다윗 왕의 지위와 연결한다.",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 사도행전 4장 25-30절 주해; Joshua W. Jipp, God’s Acts for Israel, Gentiles, and Christians, 62-63쪽.",sources:[{label:"개역개정 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKRV/ACT.4.25"},{label:"새한글성경 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKT/ACT.4.25"},{label:"SBLGNT 기준 본문",url:"https://github.com/Faithlife/SBLGNT/blob/c4d241a9c1c479a55b989ba35a4976c1d0b8052c/data/sblgnt/text/Acts.txt"},{label:"개역개정 행 4:30",url:"https://bible.bskorea.or.kr/bible/NKRV/ACT.4.30"},{label:"새한글성경 행 4:30",url:"https://bible.bskorea.or.kr/bible/NKT/ACT.4.30"}]},{id:"acts-5-32-obey-him",chapter:5,reference:"행 5:32",category:"지시 대상",title:"하나님이 자기에게 순종하는 사람들에게 주신 성령",revisedPhrase:"“하나님이 자기에게 순종하는 사람들에게 주신 성령”",newKoreanPhrase:"“하나님이 하나님께 순종하는 사람들에게 주신 성령님”",greek:"τὸ πνεῦμα τὸ ἅγιον ὃ ἔδωκεν ὁ θεὸς τοῖς πειθαρχοῦσιν αὐτῷ",literalReading:"하나님이 그에게 순종하는 사람들에게 주신 성령",possibleReading:"하나님이 하나님께 순종하는 사람들에게 주신 성령",explanation:"‘주셨다’의 주어는 ὁ θεός, 곧 하나님이다. αὐτῷ는 여기서 하나님을 가리킨다. 개역개정은 ‘자기에게’로, 새한글성경은 ‘하나님께’로 옮겨 지시 대상을 각각 다르게 드러낸다. πειθαρχοῦσιν은 ‘순종하는 사람들’을 나타내는 현재 능동 분사다. 5장 29절의 ‘사람보다 하나님께 순종해야 한다’에도 같은 동사가 쓰여, 사도들이 누구의 권위에 따르는지를 연결한다.",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 5장 29-32절 주해.",sources:[{label:"개역개정 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKRV/ACT.5.32"},{label:"새한글성경 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKT/ACT.5.32"},{label:"SBLGNT 기준 본문",url:"https://github.com/Faithlife/SBLGNT/blob/c4d241a9c1c479a55b989ba35a4976c1d0b8052c/data/sblgnt/text/Acts.txt"}]},{id:"acts-13-18-bore-or-cared",chapter:13,reference:"행 13:18",category:"본문 전승",title:"광야에서 참아 주심과 보살피심",revisedPhrase:"“그들의 소행을 참으시고”",newKoreanPhrase:"“그들의 변덕을 받아 주셨습니다”",greek:"ἐτροποφόρησεν αὐτοὺς ἐν τῇ ἐρήμῳ",literalReading:"광야에서 그들의 행실을 참아 주셨다",possibleReading:"하나님은 광야에서 그들의 행동을 참아 주셨다",variantReading:"ἐτροφοφόρησεν: 그들을 보살피셨다. ‘참아 주다’라는 ἐτροποφόρησεν과는 π와 φ가 다른 읽기다.",explanation:"SBLGNT는 ‘행실을 참아 주다’라는 동사 ἐτροποφόρησεν을 본문에 둔다. 개역개정의 ‘소행’과 새한글성경의 ‘변덕’은 이 동사의 뜻을 풀어 쓴 말이며, 원문에 행동을 뜻하는 명사가 따로 나오지는 않는다. 다른 사본의 ἐτροφοφόρησεν은 돌보고 보살핀다는 뜻이다. Johnson은 이스라엘을 돌보신 하나님의 은혜를 열거하는 문맥에 따라 후자를 선호하고, LXX 신명기 1장 31절에도 두 읽기가 전해진다고 설명한다.",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 231쪽(사도행전 13장 18절 주해).",sources:[{label:"개역개정 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKRV/ACT.13.18"},{label:"새한글성경 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKT/ACT.13.18"},{label:"SBLGNT 기준 본문",url:"https://github.com/Faithlife/SBLGNT/blob/c4d241a9c1c479a55b989ba35a4976c1d0b8052c/data/sblgnt/text/Acts.txt"}]},{id:"acts-18-22-up-to-church",chapter:18,reference:"행 18:22",category:"지시 대상",title:"올라가 문안한 교회와 생략된 예루살렘",revisedPhrase:"“올라가 교회의 안부를 물은 후에”",newKoreanPhrase:"“예루살렘으로 올라가서 교회에 인사를 드리고”",greek:"ἀναβὰς καὶ ἀσπασάμενος τὴν ἐκκλησίαν, κατέβη εἰς Ἀντιόχειαν",literalReading:"올라가 교회에 문안한 뒤 안디옥으로 내려갔다",possibleReading:"예루살렘으로 올라가 교회에 문안한 뒤 안디옥으로 내려갔다",explanation:"이 절에는 가이사랴와 안디옥이라는 지명이 나오며, ἀναβὰς(올라가)의 목적지는 생략되어 있다. 개역개정은 그 생략을 유지하고 새한글성경은 ‘예루살렘으로’를 보충한다. Dunn은 가이사랴에서 예루살렘 교회에 문안한 방문으로 읽는다. 따라서 지도에 표시한 예루살렘 경유는 이 해석에 따른 보충이다. 안디옥으로 ‘내려갔다’는 표현도 지도에서 남쪽으로 갔다는 뜻과 구분된다.",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 18장 22-23절 주해.",sources:[{label:"개역개정 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKRV/ACT.18.22"},{label:"새한글성경 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKT/ACT.18.22"},{label:"SBLGNT 기준 본문",url:"https://github.com/Faithlife/SBLGNT/blob/c4d241a9c1c479a55b989ba35a4976c1d0b8052c/data/sblgnt/text/Acts.txt"}]},{id:"acts-19-1-upper-regions",chapter:19,reference:"행 19:1",category:"낱말 의미",title:"윗지방과 내륙 지방이 가리키는 지역",revisedPhrase:"“윗지방으로 다녀 에베소에 와서”",newKoreanPhrase:"“내륙 지방을 두루 다녀서 에페수스로 내려왔다”",greek:"διελθόντα τὰ ἀνωτερικὰ μέρη … ἐλθεῖν εἰς Ἔφεσον",literalReading:"상부 지역들을 지나 에베소로 왔다",possibleReading:"내륙의 높은 지역을 거쳐 에베소로 왔다",explanation:"τὰ ἀνωτερικὰ μέρη는 높은 쪽 또는 내륙의 지역들을 가리키는 복수 표현이다. 개역개정은 ‘윗지방’, 새한글성경은 ‘내륙 지방’으로 옮겼다. 특정 도시나 정해진 행정 구역의 이름은 아니다. Dunn은 에베소로 향한 길에 리쿠스 계곡과 더 북쪽 계곡이라는 가능성을 제시한다. 지도상의 대표점과 선은 이 넓은 지역을 연결하는 복원안이며, 원문은 세부 경유 도시를 열거하지 않는다.",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 19장 1절 주해.",sources:[{label:"개역개정 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKRV/ACT.19.1"},{label:"새한글성경 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKT/ACT.19.1"},{label:"SBLGNT 기준 본문",url:"https://github.com/Faithlife/SBLGNT/blob/c4d241a9c1c479a55b989ba35a4976c1d0b8052c/data/sblgnt/text/Acts.txt"}]},{id:"acts-27-9-the-fast",chapter:27,reference:"행 27:9",category:"문화 배경",title:"금식 절기가 알려 주는 항해 시기",revisedPhrase:"“금식하는 절기가 이미 지났으므로”",newKoreanPhrase:"“금식 기간도 이미 지나가 버렸기 때문이다”",greek:"διὰ τὸ καὶ τὴν νηστείαν ἤδη παρεληλυθέναι",literalReading:"그 금식도 이미 지나갔기 때문에",possibleReading:"속죄일의 금식도 이미 지난 때였기 때문에",explanation:"τὴν νηστείαν은 특정한 ‘금식’을 가리킨다. Dunn은 이를 유대력의 속죄일 금식으로 설명한다. 가을의 이 절기가 이미 지났다는 말은 항해하기 위험한 계절에 접어들었다는 시간 표지다. 두 한국어 역본은 ‘금식하는 절기’와 ‘금식 기간’이라고 옮기며, ‘속죄일’은 그 배경을 밝혀 주는 풀이에 해당한다.",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 27장 9-12절 주해.",sources:[{label:"개역개정 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKRV/ACT.27.9"},{label:"새한글성경 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKT/ACT.27.9"},{label:"SBLGNT 기준 본문",url:"https://github.com/Faithlife/SBLGNT/blob/c4d241a9c1c479a55b989ba35a4976c1d0b8052c/data/sblgnt/text/Acts.txt"}]},{id:"acts-28-2-barbaroi",chapter:28,reference:"행 28:2",category:"문화 배경",title:"원주민과 토박이, βάρβαροι의 언어적 구분",revisedPhrase:"“원주민들이”",newKoreanPhrase:"“그 섬 토박이들은”",greek:"οἵ τε βάρβαροι",literalReading:"그 이방 사람들은",possibleReading:"그 섬의 주민들은",explanation:"βάρβαροι는 그리스어를 쓰지 않는 사람들을 가리키는 그리스인의 언어\xb7문화적 구분이다. 여기서는 멜리데 주민들을 뜻하므로 개역개정은 ‘원주민’, 새한글성경은 ‘토박이’라고 옮겼다. 이들의 행동은 같은 절의 φιλανθρωπία(친절, 인간애)로 평가된다. 누가는 주민들이 비와 추위 속의 일행에게 흔치 않은 친절을 베풀었다고 서술한다.",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 28장 1-2절 주해.",sources:[{label:"개역개정 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKRV/ACT.28.2"},{label:"새한글성경 공식 본문",url:"https://bible.bskorea.or.kr/bible/NKT/ACT.28.2"},{label:"SBLGNT 기준 본문",url:"https://github.com/Faithlife/SBLGNT/blob/c4d241a9c1c479a55b989ba35a4976c1d0b8052c/data/sblgnt/text/Acts.txt"}]},{id:"acts-2-1-supplied-they",chapter:2,reference:"행 2:1",category:"지시 대상",title:"원문에 따로 쓰이지 않은 ‘그들’은 누구인가",revisedPhrase:"“그들이 다같이 한 곳에 모였더니”",newKoreanPhrase:"“그들 모두가 같은 자리에 함께 있었다”",greek:"ἦσαν πάντες ὁμοῦ ἐπὶ τὸ αὐτό",possibleReading:"예수님을 따르던 사람들이 한곳에 함께 모여 있었다",explanation:"ἦσαν은 ‘있었다’라는 3인칭 복수 동사이고, πάντες는 ‘모두’를 뜻한다. 독립된 3인칭 대명사는 쓰이지 않았으며, 두 한국어 역본은 한국어 문장의 주어로 ‘그들’을 보탰다. ‘모두’가 포함하는 사람들의 범위에는 문맥 해석이 필요하다. Dunn은 사도행전 1장 15절의 약 120명과 연결하여 사도들보다 넓은 공동체로 읽는다.",literalReading:"모두가 같은 곳에 함께 있었다",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 2장 1절 주해.",sources:[{label:"개역개정 공식 본문",url:n(2,1)},{label:"새한글성경 공식 본문",url:o(2,1)},{label:"SBLGNT 원문",url:t},{label:"대명사 번역 연구",url:"https://translation.bible/wp-content/uploads/2024/06/moulton-1970-pronouns-in-the-new-testament.pdf"}]},{id:"acts-3-15-archegos",chapter:3,reference:"행 3:15",category:"낱말 의미",title:"‘생명의 주’인가, ‘생명의 창시자’인가",revisedPhrase:"“생명의 주”",newKoreanPhrase:"“생명의 창시자”",greek:"τὸν δὲ ἀρχηγὸν τῆς ζωῆς",possibleReading:"생명의 창시자 \xb7 생명의 선도자",explanation:"ἀρχηγός는 일을 시작하거나 앞에서 이끄는 사람을 뜻하며 ‘창시자’, ‘선도자’, ‘지도자’로 옮길 수 있다. 개역개정의 ‘주’에 해당하는 원어는 여기서 κύριος가 아닌 ἀρχηγός다. Johnson은 생명을 주는 이를 죽였다는 문장의 역설을 강조한다. 사도행전 5장 31절에서도 같은 단어가 구원자를 뜻하는 σωτήρ와 함께 쓰인다.",literalReading:"그 생명의 창시자를",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 68쪽(사도행전 3장 15절 주해).",sources:[{label:"개역개정 공식 본문",url:n(3,15)},{label:"새한글성경 공식 본문",url:o(3,15)},{label:"SBLGNT 원문",url:t},{label:"NET 번역 주석",url:i(3,15)}]},{id:"acts-7-25-his-hand",chapter:7,reference:"행 7:25",category:"지시 대상",title:"‘자기의 손’은 하나님의 손인가, 모세의 손인가",revisedPhrase:"“하나님께서 자기의 손을 통하여 구원해 주시는 것”",newKoreanPhrase:"“하나님이 자기 손을 빌려 구원해 주시는 것”",greek:"ὁ θεὸς διὰ χειρὸς αὐτοῦ δίδωσιν σωτηρίαν αὐτοῖς",possibleReading:"하나님이 모세를 통하여 이스라엘 백성을 구원해 주신다",literalReading:"하나님이 그의 손을 통하여 그들에게 구원을 주신다",explanation:"αὐτοῦ는 3인칭 단수 소유 표현 ‘그의’다. 문맥에서는 모세를 가리키며, 원문 구절에 모세라는 이름이 다시 나오지는 않는다. 구원의 주체는 하나님이고 모세는 그 수단이다. 개역개정은 ‘하나님께서’ 바로 뒤에 ‘자기의 손’을 두어 하나님의 손으로 읽기 쉽다. 새한글성경도 모세를 먼저 이름 붙였지만 ‘자기 손’은 그대로 둔다.",sources:[{label:"개역개정 공식 본문",url:n(7,25)},{label:"새한글성경 공식 본문",url:o(7,25)},{label:"SBLGNT 원문",url:t},{label:"번역자 주석",url:"https://tips.translation.bible/tip_verse/acts-725/"}]},{id:"acts-8-26-south-noon",chapter:8,reference:"행 8:26",category:"문법\xb7문장",title:"‘남쪽으로’와 ‘한낮에’가 모두 가능한 문장",revisedPhrase:"“남쪽으로 향하여 … 그 길은 광야라”",newKoreanPhrase:"“남쪽으로 … 그 길은 외진 길입니다”",greek:"κατὰ μεσημβρίαν … αὕτη ἐστὶν ἔρημος",possibleReading:"남쪽으로 향하여 예루살렘에서 가사로 내려가는 길로 가라",explanation:"μεσημβρία는 시간인 ‘정오’와 방향인 ‘남쪽’을 모두 뜻할 수 있다. κατὰ μεσημβρίαν도 두 방식으로 읽혀 왔으며, 개역개정과 새한글성경은 방향을 택했다. Johnson은 가사와 예루살렘의 지리적 관계 및 κατά와의 결합을 근거로 ‘남쪽으로’를 선호한다. ‘한낮에’는 같은 원문을 시간 표현으로 이해한 대안이다.",literalReading:"남쪽으로 가라 / 한낮에 가라",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 154쪽(사도행전 8장 26절 주해).",sources:[{label:"개역개정 공식 본문",url:n(8,26)},{label:"새한글성경 공식 본문",url:o(8,26)},{label:"SBLGNT 원문",url:t},{label:"NET 번역 주석",url:i(8,26)}]},{id:"acts-8-26-this-road-or-gaza",chapter:8,reference:"행 8:26",category:"지시 대상",title:"‘이것’은 길인가, 가사 성읍인가",revisedPhrase:"“그 길은 광야라”",newKoreanPhrase:"“그 길은 외진 길입니다”",greek:"αὕτη ἐστὶν ἔρημος",possibleReading:"이 길은 외딴 길이다 / 이 가사는 버려진 곳이다",explanation:"αὕτη는 여성 단수 지시대명사다. 앞 문장의 ‘길’(ὁδός)과 ‘가사’(Γάζα)는 모두 여성형이므로 지시 대상의 후보가 된다. 두 한국어 역본은 ‘길’을 가리킨다고 풀어 썼다. ἔρημος는 사람이 살지 않거나 외딴 상태를 나타낸다. 개역개정의 ‘광야’는 지형을, 새한글성경의 ‘외진 길’은 사람의 왕래가 드문 상태를 더 선명하게 드러낸다.",literalReading:"이것은 외딴 곳이다",sources:[{label:"개역개정 공식 본문",url:n(8,26)},{label:"새한글성경 공식 본문",url:o(8,26)},{label:"SBLGNT 원문",url:t},{label:"대명사 번역 연구",url:"https://translation.bible/wp-content/uploads/2024/06/moulton-1970-pronouns-in-the-new-testament.pdf"}]},{id:"acts-10-34-partiality",chapter:10,reference:"행 10:34",category:"낱말 의미",title:"외모를 본다는 관용구와 편파적인 대우",revisedPhrase:"“사람의 외모를 보지 아니하시고”",newKoreanPhrase:"“겉모습을 보고 차별하시는 분이 아닙니다”",greek:"οὐκ ἔστιν προσωπολήμπτης ὁ θεός",possibleReading:"하나님은 사람을 편파적으로 대하지 않으신다",explanation:"προσωπολήμπτης는 신분이나 지위에 따라 사람을 편드는 이를 가리킨다. ‘얼굴을 받아 준다’는 표현에서 나온 말로, 외관의 아름다움만을 뜻하지 않는다. 고넬료를 만난 베드로는 이어지는 35절에서 어떤 민족에 속하든 하나님을 경외하고 의를 행하는 사람을 하나님이 받으신다고 말한다. 이 문맥에서 두 역본의 ‘외모’와 ‘겉모습’은 민족과 사회적 지위를 따라 차별하는 태도와 연결된다.",literalReading:"하나님은 사람을 편파적으로 대하는 분이 아니시다",sources:[{label:"개역개정 공식 본문",url:n(10,34)},{label:"새한글성경 공식 본문",url:o(10,34)},{label:"SBLGNT 원문",url:t},{label:"NET 번역 주석",url:i(10,34)}]},{id:"acts-11-20-hellenists",chapter:11,reference:"행 11:20",category:"본문 전승",title:"안디옥에서 복음을 들은 사람은 ‘헬라인’인가",revisedPhrase:"“헬라인에게도 말하여”",newKoreanPhrase:"“그리스말을 쓰는 사람들한테도”",greek:"πρὸς τοὺς Ἑλληνιστάς",possibleReading:"그리스어권 사람들에게도 주 예수를 전했다",explanation:"Ἑλληνιστάς는 그리스어를 쓰는 사람들을 가리키며, 사도행전 6장 1절과 9장 29절에서는 헬라파 유대인에게 쓰인다. 이 구절은 19절의 ‘유대인에게만’과 대조되어 청중의 범위가 쟁점이 된다. SBLGNT는 Ἑλληνιστάς를 본문에 두지만, Dunn과 Johnson은 이 대조를 근거로 Ἕλληνας 읽기를 선호한다. 개역개정은 ‘헬라인’, 새한글성경은 ‘그리스말을 쓰는 사람들’이라고 옮긴다.",literalReading:"그리스어를 쓰는 사람들에게",variantReading:"πρὸς τοὺς Ἕλληνας: 헬라인들에게. SBLGNT의 Ἑλληνιστάς와 구별되는 사본 읽기다.",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 11장 20절 주해. Luke Timothy Johnson, The Acts of the Apostles, 203쪽(사도행전 11장 20절 주해).",sources:[{label:"개역개정 공식 본문\xb7각주",url:n(11,20)},{label:"새한글성경 공식 본문",url:o(11,20)},{label:"SBLGNT 원문",url:t},{label:"공개 본문비평 주석",url:"https://www.bibliaplus.org/en/commentaries/428/a-textual-commentary-on-the-greek-new-testament-by-bruce-m-metzger/acts/11/20"}]},{id:"acts-16-16-python",chapter:16,reference:"행 16:16",category:"문화 배경",title:"‘점치는 귀신’ 뒤에 있는 피톤 신탁의 세계",revisedPhrase:"“점치는 귀신 들린 여종”",newKoreanPhrase:"“점치는 영에 붙들린 어떤 여자종”",greek:"ἔχουσαν πνεῦμα πύθωνα",possibleReading:"피톤의 영을 지닌 여종",explanation:"πύθων은 본래 델포이 신탁과 아폴론 전승에 연결된 피톤을 가리킨다. 개역개정은 기능을 분명히 전달하지만, 빌립보 사람들이 이 여종을 그리스\xb7로마의 신탁 문화 안에서 이해했다는 배경은 보이지 않는다.",sources:[{label:"개역개정 공식 본문",url:n(16,16)},{label:"새한글성경 공식 본문",url:o(16,16)},{label:"SBLGNT 원문",url:t},{label:"NET 번역 주석",url:i(16,16)}]},{id:"acts-17-18-seed-picker",chapter:17,reference:"행 17:18",category:"문화 배경",title:"‘말쟁이’보다 모욕적인 ‘씨앗 줍는 자’",revisedPhrase:"“이 말쟁이가”",newKoreanPhrase:"“이 떠버리가”",greek:"ὁ σπερμολόγος οὗτος",possibleReading:"이 잡동사니 지식이나 주워 모으는 자가",explanation:"σπερμολόγος는 씨앗을 쪼아 먹는 새나 시장의 부스러기를 줍는 사람에서 나온 비하 표현이다. 여기서는 남의 생각을 조금씩 주워 와 아는 체하는 사람이라는 조롱에 가깝다. ‘말이 많은 사람’이라는 뜻만으로는 아덴 철학자들의 경멸이 약해진다.",sources:[{label:"개역개정 공식 본문",url:n(17,18)},{label:"새한글성경 공식 본문",url:o(17,18)},{label:"SBLGNT 원문",url:t},{label:"NET 번역 주석",url:i(17,18)}]},{id:"acts-17-22-religious",chapter:17,reference:"행 17:22",category:"낱말 의미",title:"‘종교심이 많다’는 칭찬인가 비판인가",revisedPhrase:"“범사에 종교심이 많도다”",newKoreanPhrase:"“얼마나 신을 두려워하는지”",greek:"δεισιδαιμονεστέρους",possibleReading:"매우 종교적이다 / 다소 미신적이다",explanation:"δεισιδαιμονεστέρους는 비교급 형태로, 여기서는 종교에 대한 관심이 크다는 뜻을 강조할 수 있다. 관련 낱말에는 신을 공경한다는 긍정적 뜻과 미신적이라는 부정적 뜻이 함께 있다. 개역개정은 ‘종교심이 많다’, 새한글성경은 ‘신을 두려워한다’로 옮겼다. Dunn은 연설을 시작하며 청중에게 건네는 예의 있는 인정으로 읽되, 뒤이어 그들이 알지 못하는 하나님을 설명하는 전개와 연결한다.",literalReading:"여러분이 매우 신들을 두려워하는 것으로 봅니다",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 17장 22-23절 주해.",sources:[{label:"개역개정 공식 본문",url:n(17,22)},{label:"새한글성경 공식 본문",url:o(17,22)},{label:"SBLGNT 원문",url:t},{label:"NET 번역 주석",url:i(17,22)}]},{id:"acts-19-2-believing",chapter:19,reference:"행 19:2",category:"문법\xb7문장",title:"‘믿을 때’인가, ‘믿은 뒤’인가",revisedPhrase:"“너희가 믿을 때에 성령을 받았느냐”",newKoreanPhrase:"“믿었을 때에 성령을 받았습니까?”",greek:"Εἰ πνεῦμα ἅγιον ἐλάβετε πιστεύσαντες;",possibleReading:"믿었을 때 성령을 받았느냐 / 믿은 뒤 성령을 받았느냐",explanation:"πιστεύσαντες는 ‘믿다’의 부정과거 능동 분사로, 주동사 ἐλάβετε(받았느냐)와 같은 사람들을 주어로 삼는다. 믿게 된 일을 ‘성령을 받다’와 연결하면서 ‘믿었을 때’ 또는 ‘믿은 뒤’로 옮길 수 있다. 두 한국어 역본은 ‘때’를 택했다. Dunn은 누가의 성령 서술과 이 문답의 흐름에 따라 ‘믿었을 때’를 선호한다. 이어지는 대화는 그들의 믿음과 요한의 세례가 예수님을 향하도록 이끈다.",literalReading:"믿었을 때 성령을 받았습니까?",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 19장 2-4절 주해.",sources:[{label:"개역개정 공식 본문",url:n(19,2)},{label:"새한글성경 공식 본문",url:o(19,2)},{label:"SBLGNT 원문",url:t},{label:"NET 본문\xb7주석",url:i(19,2)}]},{id:"acts-20-28-own-blood",chapter:20,reference:"행 20:28",category:"문법\xb7문장",title:"‘자기 피’와 ‘자기 아들의 피’",revisedPhrase:"“하나님이 자기 피로 사신 교회”",newKoreanPhrase:"“자신의 피를 통해서 자신의 것으로 만드신 교회”",greek:"διὰ τοῦ αἵματος τοῦ ἰδίου",possibleReading:"자기 자신의 피로 / 자기에게 속한 이의 피, 곧 자기 아들의 피로",explanation:"τοῦ ἰδίου를 ‘자기 자신의’라는 수식어로 읽으면 ‘자기 피’가 된다. 이를 ‘자기에게 속한 이’라는 명사적 표현으로 읽는 해석에서는 ‘자기 아들의 피’로 풀 수 있다. ‘아들’을 뜻하는 υἱός는 이 원문에 쓰이지 않으므로 후자는 지시 대상을 보충한 번역이다. 별도로 ‘하나님의 교회’와 ‘주의 교회’라는 사본 차이가 있다. Johnson은 ‘하나님의 교회’를 택하고, ‘자기 아들의 피’ 해석도 가능한 대안으로 다룬다.",literalReading:"그 자신의 피를 통하여",variantReading:"τὴν ἐκκλησίαν τοῦ κυρίου: 주의 교회. SBLGNT는 이 자리에 τοῦ θεοῦ, 곧 하나님의 교회를 둔다.",commentary:"Luke Timothy Johnson, The Acts of the Apostles, 363쪽(사도행전 20장 28절 주해). James D. G. Dunn, The Acts of the Apostles, 사도행전 20장 28절 주해.",sources:[{label:"개역개정 공식 본문\xb7각주",url:n(20,28)},{label:"새한글성경 공식 본문",url:o(20,28)},{label:"SBLGNT 원문",url:t},{label:"NET 번역\xb7본문비평 주석",url:i(20,28)}]},{id:"acts-21-19-his-ministry",chapter:21,reference:"행 21:19",category:"지시 대상",title:"‘자기의 사역’은 하나님의 사역인가, 바울의 사역인가",revisedPhrase:"“하나님이 자기의 사역으로 말미암아 … 하신 일”",newKoreanPhrase:"“자기의 섬김을 통하여 하나님이 … 행하신 일들”",greek:"ὧν ἐποίησεν ὁ θεὸς … διὰ τῆς διακονίας αὐτοῦ",possibleReading:"하나님이 바울의 사역을 통하여 이방인 가운데서 하신 일",literalReading:"하나님이 … 그의 사역을 통하여 행하신 일들",explanation:"αὐτοῦ는 3인칭 단수 소유 표현 ‘그의’다. 여기서 일을 행한 분은 하나님이고, 문맥상 ‘그’는 바울이다. ‘바울의 사역’은 지시 대상을 이름으로 풀어 쓴 번역이다. 개역개정의 ‘하나님이 자기의 사역으로’는 ‘자기’를 하나님에게 붙여 읽게 한다. 새한글성경은 ‘자기의 섬김’을 먼저 놓은 뒤 ‘하나님이’를 써서 사역의 주인과 행위 주체를 구별한다.",sources:[{label:"개역개정 공식 본문",url:n(21,19)},{label:"새한글성경 공식 본문",url:o(21,19)},{label:"SBLGNT 원문",url:t},{label:"NET 번역 주석",url:i(21,19)}]},{id:"acts-22-9-hearing",chapter:9,relatedChapters:[9,22],reference:"행 9:7; 22:9",category:"문법\xb7문장",title:"동행자들은 소리를 들었는가, 듣지 못했는가",revisedPhrase:"“소리는 듣지 못하더라”",newKoreanPhrase:"“말씀하시는 분의 목소리는 듣지 못했습니다”",greek:"ἀκούοντες μὲν τῆς φωνῆς (9:7) \xb7 τὴν δὲ φωνὴν οὐκ ἤκουσαν (22:9)",possibleReading:"소리는 들었으나 사울에게 하신 말씀의 내용을 알아듣지 못했다",explanation:"사도행전 9장 7절은 동행자들이 소리를 들었다고 하고, 22장 9절은 말하는 이의 목소리를 듣지 못했다고 말한다. 앞에서는 φωνή가 속격, 뒤에서는 목적격으로 쓰인다. ἀκούω에는 ‘듣다’와 ‘알아듣다’의 뜻이 있어 두 서술을 소리의 지각과 내용의 이해로 구분하는 해석이 가능하다. 이 구분은 두 장면을 연결한 문맥적 해석이며, 격의 차이만으로 뜻이 자동 결정되는 규칙은 아니다.",literalReading:"소리는 들으면서(9:7) \xb7 그 목소리는 듣지 못했다(22:9)",sources:[{label:"개역개정 행 22장",url:n(22,9)},{label:"개역개정 행 9장",url:n(9,7)},{label:"새한글성경 행 22장",url:o(22,9)},{label:"새한글성경 행 9장",url:o(9,7)},{label:"NET 번역 주석",url:i(22,9)}]},{id:"acts-24-14-sect",chapter:24,reference:"행 24:5, 14",category:"낱말 의미",title:"1세기의 ‘파’가 후대의 ‘이단’이 될 때",revisedPhrase:"“나사렛 이단” \xb7 “이단이라 하는 도”",newKoreanPhrase:"“나사렛 사람들 분파” \xb7 “분파라고 말하는 그 믿음의 길”",greek:"αἵρεσιν",possibleReading:"나사렛파 \xb7 그들이 한 분파라고 부르는 그 길",explanation:"αἵρεσις는 사도행전에서 특정 집단이나 분파를 가리킨다. 5장 17절의 사두개파와 15장 5절의 바리새파에도 같은 말이 쓰인다. 더둘로는 24장 5절에서 바울을 나사렛파의 우두머리라고 고발하고, 바울은 14절에서 그들이 분파라고 부르는 ‘그 길’을 따라 조상의 하나님을 섬긴다고 답한다. 새한글성경의 ‘분파’는 이 사회적 집단 구분을 드러내고, 개역개정의 ‘이단’은 오늘날 교리적 판단으로 읽히기 쉽다.",literalReading:"그들이 분파라고 부르는 그 길",sources:[{label:"개역개정 공식 본문",url:n(24,14)},{label:"새한글성경 공식 본문",url:o(24,14)},{label:"SBLGNT 원문",url:t},{label:"NET 본문",url:i(24,14)}]},{id:"acts-26-28-en-oligo",chapter:26,reference:"행 26:28",category:"문법\xb7문장",title:"아그립바의 말은 질문인가, 빈정거림인가",revisedPhrase:"“적은 말로 나를 권하여 … 되게 하려 하는도다”",newKoreanPhrase:"“잠깐 사이에 나를 설득해서 … 만들려고 하는구나”",greek:"Ἐν ὀλίγῳ με πείθεις Χριστιανὸν ποιῆσαι",possibleReading:"그렇게 짧은 말이나 시간으로 나를 그리스도인으로 설득하려는가? / 적은 노력으로 나를 그리스도인으로 만들려는가?",explanation:"ἐν ὀλίγῳ는 ‘짧은 시간에’ 또는 ‘적은 말이나 노력으로’라는 뜻을 허용한다. 개역개정은 ‘적은 말로’, 새한글성경은 ‘잠깐 사이에’를 택했다. 평서문으로 옮겨도 말투에는 질문이나 반어의 여지가 있다. Dunn은 아그립바가 거의 회심했다는 읽기와 현대 역본들의 반어적 읽기를 구분하며, ‘그리스도인 노릇을 하게 한다’는 조롱의 뉘앙스를 제시한다.",literalReading:"짧은 시간이나 적은 노력으로 나를 설득하여 그리스도인이 되게 하려 하는군",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 26장 28절 주해.",sources:[{label:"개역개정 공식 본문\xb7각주",url:n(26,28)},{label:"새한글성경 공식 본문",url:o(26,28)},{label:"SBLGNT 원문",url:t},{label:"NET 번역 주석",url:i(26,28)}]},{id:"acts-28-4-justice",chapter:28,reference:"행 28:4",category:"문화 배경",title:"‘공의’가 의인화된 디케로 들릴 수 있다",revisedPhrase:"“공의가 그를 살지 못하게 함이로다”",newKoreanPhrase:"“디케(정의의 여신)가 그를 살려 두지 않는군요!”",greek:"ἡ δίκη ζῆν οὐκ εἴασεν",possibleReading:"정의의 여신 디케가 그를 살려 두지 않았다",explanation:"δίκη는 정의나 응보를 뜻하고, 그리스 문학에서는 정의의 여신 디케로 의인화되기도 한다. 멜리데 주민들은 바다에서 살아남은 사람이 독사에 물리자 살인자에게 응보가 닥쳤다고 생각한다. 개역개정은 ‘공의’라는 명사로, 새한글성경은 ‘디케(정의의 여신)’라는 이름과 설명으로 옮긴다. Dunn은 이 장면을 주민들이 신적 정의의 판결을 기다리는 이야기로 설명한다.",literalReading:"정의가 그를 살도록 내버려 두지 않았다",commentary:"James D. G. Dunn, The Acts of the Apostles, 사도행전 28장 3-4절 주해.",sources:[{label:"개역개정 공식 본문",url:n(28,4)},{label:"새한글성경 공식 본문",url:o(28,4)},{label:"SBLGNT 원문",url:t},{label:"NET 번역 주석",url:i(28,4)}]}]}}]);